import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def add_to_book(id_, side, price, qty, seq):
        book[id_] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    def pop_valid_buy():
        while buy_heap:
            negprice, seq, id_ = buy_heap[0]
            info = book.get(id_)
            if info is None or not info.get('active') or info.get('qty', 0) <= 0:
                heapq.heappop(buy_heap)
                continue
            return negprice, seq, id_
        return None

    def pop_valid_sell():
        while sell_heap:
            price, seq, id_ = sell_heap[0]
            info = book.get(id_)
            if info is None or not info.get('active') or info.get('qty', 0) <= 0:
                heapq.heappop(sell_heap)
                continue
            return price, seq, id_
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            id_ = order[1]
            info = book.get(id_)
            if info is not None and info.get('active'):
                info['active'] = False
                del book[id_]
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'market':
            id_, side, qty = order[1], order[2], order[3]
            price = None
        else:
            id_, side, price, qty = order[1], order[2], order[3], order[4]

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = pop_valid_sell()
                if top is None:
                    break
                sell_price, sell_seq, sell_id = top
                if typ != 'market' and sell_price > price:
                    break
                sell_info = book[sell_id]
                trade_qty = min(remaining, sell_info['qty'])
                trades.append([id_, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                sell_info['qty'] -= trade_qty
                if sell_info['qty'] == 0:
                    sell_info['active'] = False
                    del book[sell_id]
                    heapq.heappop(sell_heap)
        else:
            # side == 'sell'
            while remaining > 0:
                top = pop_valid_buy()
                if top is None:
                    break
                negprice, buy_seq, buy_id = top
                buy_price = -negprice
                if typ != 'market' and buy_price < price:
                    break
                buy_info = book[buy_id]
                trade_qty = min(remaining, buy_info['qty'])
                trades.append([buy_id, id_, buy_price, trade_qty])
                remaining -= trade_qty
                buy_info['qty'] -= trade_qty
                if buy_info['qty'] == 0:
                    buy_info['active'] = False
                    del book[buy_id]
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            add_to_book(id_, side, price, remaining, seq)

    return trades

